      "    ['a/b/c{d}e', {}, 'a/b/c{d}e'],",
      "",
      "    // should escape closing braces when open is not defined",
      "    ['{a,b}c,d}', {}, '(a|b)c,d}'],",
      "    ['a,b,c,d}', {}, 'a,b,c,d}'],",
