      "",
      "    it('should expand positive ranges with negative steps:', () => {",
      "      equal('{10..0..-2}', ['10', '8', '6', '4', '2', '0']);",
      "    });",
      "  });",
      "",
      "  describe('steps > negative ranges', () => {",
