      "    it('should expand alpha ranges with steps', () => {",
      "      equal('{a..e..2}', ['a', 'c', 'e']);",
      "      equal('{E..A..2}', ['E', 'C', 'A']);",
      "      equal('{a..z}', ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z']);",
      "      equal('{a..z..2}', ['a', 'c', 'e', 'g', 'i', 'k', 'm', 'o', 'q', 's', 'u', 'w', 'y']);",
