      "    });",
      "  });",
      "",
      "  describe('padding', () => {",
      "    it('unwanted zero-padding -- fixed post-bash-4.0', () => {",
      "      equal('{10..0..2}', ['10', '8', '6', '4', '2', '0']);",
      "      equal('{10..0..-2}', ['10', '8', '6', '4', '2', '0']);",
      "      equal('{-50..-0..5}', ['-50', '-45', '-40', '-35', '-30', '-25', '-20', '-15', '-10', '-5', '0']);",
      "    });",
      "  });",
      "",
      "  describe('ranges', () => {",
      "    const fixtures = [",
