const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const Module = require('node:module');
const { spawnSync } = require('node:child_process');
const { createHash } = require('node:crypto');
const root = path.resolve(__dirname, '../..');
const patchPath = path.join(root, 'patches/braces@3.0.3.patch');
const patchSha256 = '6fd0203dc23690cde48857c39c94d8a237e8b5f588339645b1c02851d234f4a9';
const sha256 = value => createHash('sha256').update(value).digest('hex');
const packageRoot = process.env.WUYAN_SECURITY_PATCH_PACKAGE_PATH
  ? fs.realpathSync(process.env.WUYAN_SECURITY_PATCH_PACKAGE_PATH)
  : path.dirname(Module.createRequire(fs.realpathSync(path.join(root, 'node_modules/.pnpm/node_modules/micromatch/package.json'))).resolve('braces/package.json'));
const packageRequire = Module.createRequire(path.join(packageRoot, 'package.json'));
const patchText = fs.readFileSync(patchPath, 'utf8');
assert.equal(sha256(patchText), patchSha256, 'reviewed patch bytes changed');
const patchSections = new Map();
let section;
let hunk;
for (const line of patchText.split('\n')) {
  if (line.startsWith('+++ b/')) {
    const file = line.slice(6);
    assert(Object.hasOwn(ORIGINAL_HASHES, file), 'unexpected patch path: ' + file);
    section = [];
    patchSections.set(file, section);
    hunk = undefined;
  } else if (line.startsWith('@@ ')) {
    const match = /^@@ -(\d+),(\d+) \+(\d+),(\d+) @@/.exec(line);
    assert(match, 'unsupported patch hunk');
    hunk = { oldStart: Number(match[1]), oldCount: Number(match[2]), newStart: Number(match[3]), newCount: Number(match[4]), lines: [] };
    section.push(hunk);
  } else if (hunk && /^[ +\-]/.test(line) && !line.startsWith('--- ') && !line.startsWith('+++ ')) {
    hunk.lines.push(line);
  }
}
assert.deepEqual([...patchSections.keys()].sort(), ['lib/compile.js', 'lib/expand.js', 'lib/parse.js', 'lib/stringify.js', 'lib/utils.js']);

function reversePatch(source, hunks) {
  const input = source.split('\n');
  const output = [];
  let cursor = 0;
  for (const item of hunks) {
    const before = item.lines.filter(line => line[0] !== '+').map(line => line.slice(1));
    const after = item.lines.filter(line => line[0] !== '-').map(line => line.slice(1));
    assert.equal(before.length, item.oldCount);
    assert.equal(after.length, item.newCount);
    const start = item.newStart - 1;
    assert(start >= cursor);
    assert.deepEqual(input.slice(start, start + after.length), after, 'installed package does not match reviewed patch');
    output.push(...input.slice(cursor, start), ...before);
    cursor = start + after.length;
  }
  output.push(...input.slice(cursor));
  return output.join('\n');
}

function inventory(directory, prefix = '') {
  return fs.readdirSync(path.join(directory, prefix), { withFileTypes: true }).flatMap(entry => {
    if (entry.name === 'node_modules') return [];
    const relative = path.posix.join(prefix, entry.name);
    assert(!entry.isSymbolicLink(), 'unexpected symlink inside package: ' + relative);
    return entry.isDirectory() ? inventory(directory, relative) : [{ path: relative, sha256: sha256(fs.readFileSync(path.join(directory, relative))) }];
  }).sort((a, b) => a.path.localeCompare(b.path));
}

const installedInventory = inventory(packageRoot);
assert.deepEqual(installedInventory.map(item => item.path).sort(), Object.keys(ORIGINAL_HASHES).sort(), 'package file inventory changed');
const originalSources = new Map();
for (const file of Object.keys(ORIGINAL_HASHES)) {
  const installed = fs.readFileSync(path.join(packageRoot, file), 'utf8');
  const original = patchSections.has(file) ? reversePatch(installed, patchSections.get(file)) : installed;
  assert.equal(sha256(original), ORIGINAL_HASHES[file], 'upstream source hash mismatch: ' + file);
  originalSources.set(file, original);
}
const packageMetadata = JSON.parse(originalSources.get('package.json'));
assert.equal(packageMetadata.name, 'braces');
assert.equal(packageMetadata.version, '3.0.3');
assert.equal(packageMetadata.license, 'MIT');
assert.equal(packageRequire('fill-range/package.json').version, '7.1.1', 'review upstream tests with a changed fill-range');

function originalLoader() {
  const cache = new Map();
  function load(file) {
    if (cache.has(file)) return cache.get(file).exports;
    assert(originalSources.has(file), 'unexpected original module: ' + file);
    const filename = path.join(packageRoot, file);
    const loaded = new Module(filename, module);
    loaded.filename = filename;
    loaded.paths = Module._nodeModulePaths(path.dirname(filename));
    cache.set(file, loaded);
    loaded.require = request => {
      if (!request.startsWith('.')) return packageRequire(request);
      const resolved = Module._resolveFilename(request, loaded);
      return load(path.relative(packageRoot, resolved).replaceAll('\\', '/'));
    };
    loaded._compile(originalSources.get(file), filename);
    return loaded.exports;
  }
  return load;
}

function nestedAst(depth) {
  let node = { type: 'root', nodes: [] };
  for (let index = 0; index < depth; index++) node = { type: 'root', nodes: [node] };
  return node;
}

function attackInput(kind, depth) {
  if (kind === 'brace') return '{'.repeat(depth) + 'x' + '}'.repeat(depth);
  if (kind === 'paren') return '('.repeat(depth) + 'x' + ')'.repeat(depth);
  if (kind === 'mixed') return '{('.repeat(depth) + 'x' + ')}'.repeat(depth);
  if (kind === 'ast') return nestedAst(depth);
  if (kind === 'cycle') {
    const node = { type: 'root', nodes: [] };
    node.nodes.push(node);
    return node;
  }
  if (kind === 'parent-cycle') {
    const parent = { type: 'paren', nodes: [], queue: [] };
    parent.parent = parent;
    return { type: 'root', nodes: [{ type: 'paren', nodes: [], parent }] };
  }
  throw new Error('unknown attack: ' + kind);
}

if (process.argv[2] === '--probe') {
  // Patched probes execute the real installed files. Only the negative control
  // reconstructs pristine sources in memory using the reviewed patch in reverse.
  const braces = process.argv[3] === 'original'
    ? originalLoader()('index.js')
    : packageRequire('./index.js');
  const [kind, operation, depth = '4000'] = process.argv[4].split(':');
  try {
    braces[operation](attackInput(kind, Number(depth)));
    console.log(JSON.stringify({ result: 'accepted' }));
  } catch (error) {
    console.log(JSON.stringify({ result: error.name, code: error.code || null, message: error.message }));
  }
  process.exit(0);
}

if (process.argv.includes('--inventory')) {
  console.log(JSON.stringify({ package: 'braces', version: '3.0.3', packageRoot, patchSha256, testSha256: sha256(fs.readFileSync(__filename)), installedInventory }, null, 2));
  process.exit(0);
}

const { test } = require('node:test');
const patched = packageRequire('./index.js');
const original = originalLoader()('index.js');

test('installed bytes, complete inventory, upstream package identity and MIT match the reviewed patch', () => {
  assert.equal(installedInventory.length, 10);
  assert.equal(patchSections.size, 5);
});

test('all 12 offline upstream test fixtures match the pinned upstream Git blobs', () => {
  assert.equal(UPSTREAM_SUITES.length, 12);
  for (const suite of UPSTREAM_SUITES) {
    const source = suite.lines.join('\n');
    const actual = createHash('sha1').update('blob ' + Buffer.byteLength(source) + '\0').update(source).digest('hex');
    assert.equal(actual, suite.gitBlob, suite.name);
  }
});

let upstreamCount = 0;
for (const suite of UPSTREAM_SUITES) {
  const groups = [];
  const describe = (name, callback) => {
    groups.push(name);
    callback();
    groups.pop();
  };
  const it = (name, callback) => {
    upstreamCount++;
    test('upstream/' + suite.name + '/' + [...groups, name].join(' / '), callback);
  };
  const fixtureRequire = request => {
    if (request === 'assert') return require('node:assert');
    if (request === 'mocha') return {};
    if (request === '..') return patched;
    if (request === '../lib/parse') return packageRequire('./lib/parse.js');
    if (request === '../lib/compile') return packageRequire('./lib/compile.js');
    if (request === '../lib/expand') return packageRequire('./lib/expand.js');
    // Upstream fixtures provide expected output. Any unexpected request for a
    // live Bash oracle fails rather than executing an additional shell.
    if (request === 'bash-path') return () => { throw new Error('offline fixtures must not invoke Bash'); };
    if (request === 'child_process') return Object.freeze({ spawnSync() { throw new Error('offline fixtures must not spawn a shell'); } });
    throw new Error('unsupported upstream test import: ' + request);
  };
  new Function('require', 'describe', 'it', suite.lines.join('\n'))(fixtureRequire, describe, it);
}
test('upstream test discovery is non-empty and has no synthetic skipped tests', () => {
  assert.equal(upstreamCount, 764, 'the pinned upstream suite test count changed');
});

test('1,239 normal pattern/option comparisons match pristine braces 3.0.3', () => {
  const syntax = ['a', '', '{}', '{a,b}', '{,a}', '{a,,b}', '{a,{b,c}}', '{1..6}', '{6..1}', '{01..05}', '{a..e}', '{1..9..2}', '{9..1..2}', 'a/{x,y}/**/*.{js,tsx}', 'x/\\{a,b\\}', '$' + '{value}', 'a[{}]b', 'a("{x,y}")', '{a', 'a}', '{{x}}', '(a|b)', '{..a,b}'];
  const generated = [];
  for (const a of ['src', 'test', 'lib']) for (const b of ['js', 'tsx', 'scss']) for (const c of ['one', 'two']) {
    generated.push(a + '/{a,b}/' + c + '/*.{' + b + ',map}', a + '/{1..4}/{' + c + ',x}.' + b);
  }
  const options = [{}, { expand: true }, { escapeInvalid: true }, { keepEscaping: true }, { keepQuotes: true }, { nodupes: true, noempty: true }, { rangeLimit: 3 }];
  const outcome = callback => {
    try { return { value: callback() }; } catch (error) { return { error: error.name, message: error.message }; }
  };
  let count = 0;
  for (const pattern of [...syntax, ...generated]) for (const opts of options) for (const operation of ['compile', 'expand', 'stringify']) {
    assert.deepEqual(outcome(() => patched[operation](pattern, opts)), outcome(() => original[operation](pattern, opts)), operation + ': ' + pattern);
    count++;
  }
  assert.equal(count, 1239);
});

const depthError = error => error instanceof SyntaxError && error.code === 'ERR_BRACES_DEPTH';
for (const operation of ['compile', 'expand', 'stringify']) {
  test(operation + ': direct AST depths 100/101 and ordinary 99-container inputs', () => {
    assert.deepEqual(patched[operation](nestedAst(100)), original[operation](nestedAst(100)));
    assert.throws(() => patched[operation](nestedAst(101)), depthError);
    for (const [open, close] of [['{', '}'], ['(', ')']]) {
      const pattern = open.repeat(99) + 'x' + close.repeat(99);
      assert.deepEqual(patched[operation](pattern), original[operation](pattern));
    }
  });
}
test('parse: 100/101 container boundary and caller options cannot raise the hard limit', () => {
  for (const [open, close] of [['{', '}'], ['(', ')']]) {
    assert.doesNotThrow(() => patched.parse(open.repeat(100) + 'x' + close.repeat(100)));
    for (const opts of [{}, { maxDepth: Infinity }, { maxLength: Infinity }, { maxDepth: NaN }, { maxDepth: 1000000 }]) {
      assert.throws(() => patched.parse(open.repeat(101) + 'x' + close.repeat(101), opts), depthError);
    }
  }
});
test('parser container depth and walker terminal-node depth have explicit distinct boundaries', () => {
  const pattern = '{'.repeat(100) + 'x' + '}'.repeat(100);
  assert.doesNotThrow(() => patched.parse(pattern));
  assert.deepEqual(patched.expand(pattern), original.expand(pattern));
  assert.throws(() => patched.compile(pattern), depthError);
  assert.throws(() => patched.stringify(pattern), depthError);
  assert.throws(() => patched(pattern), depthError);
  assert.throws(() => patched.create(pattern), depthError);
});
test('quoted, escaped and bracket-literal delimiters do not consume container depth', () => {
  const literal = '{'.repeat(150) + 'x' + '}'.repeat(150);
  for (const pattern of ['"' + literal + '"', '[' + literal + ']', '\\{'.repeat(150) + 'x' + '\\}'.repeat(150)]) {
    for (const operation of ['compile', 'expand', 'stringify']) {
      assert.deepEqual(patched[operation](pattern), original[operation](pattern));
    }
  }
});
test('shared acyclic AST nodes remain supported without false cycle rejection', () => {
  const leaf = { type: 'text', value: 'x' };
  for (const operation of ['compile', 'expand', 'stringify']) {
    const tree = () => ({ type: 'root', nodes: [leaf, leaf] });
    assert.deepEqual(patched[operation](tree()), original[operation](tree()));
  }
});

const attacks = [];
for (const operation of ['parse', 'compile', 'expand', 'stringify']) for (const kind of ['brace', 'paren']) attacks.push(kind + ':' + operation + ':4000');
for (const operation of ['compile', 'expand', 'stringify']) for (const kind of ['ast', 'cycle']) attacks.push(kind + ':' + operation + ':12000');
attacks.push('mixed:compile:2000', 'parent-cycle:expand');
assert.equal(attacks.length, 16);

function probe(variant, scenario) {
  const child = spawnSync(process.execPath, ['--stack-size=512', '--max-old-space-size=128', __filename, '--probe', variant, scenario], {
    encoding: 'utf8', windowsHide: true, timeout: 2500, maxBuffer: 1024 * 1024,
    env: { ...process.env, WUYAN_SECURITY_PATCH_PACKAGE_PATH: packageRoot },
  });
  if (child.error) return { result: child.error.code };
  assert.equal(child.status, 0, child.stderr);
  return JSON.parse(child.stdout.trim().split('\n').at(-1));
}
for (const scenario of attacks) {
  test('installed patch rejects ' + scenario + ' with controlled depth error', () => {
    const result = probe('patched', scenario);
    assert.equal(result.result, 'SyntaxError', JSON.stringify(result));
    assert.equal(result.code, 'ERR_BRACES_DEPTH', JSON.stringify(result));
  });
  test('pristine negative control still demonstrates ' + scenario, () => {
    const result = probe('original', scenario);
    if (scenario === 'parent-cycle:expand') assert.equal(result.result, 'ETIMEDOUT');
    else if (scenario.includes(':parse:') || scenario === 'paren:expand:4000') assert.equal(result.result, 'accepted');
    else {
      assert.equal(result.result, 'RangeError', JSON.stringify(result));
      assert.match(result.message, /Maximum call stack size exceeded/);
    }
  });
}
